def transform(grid):
    # Recolor every 9-valued full-height or full-width separator to 2.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for c in range(w):
        if all(grid[r][c] == 9 for r in range(h)):
            for r in range(h):
                out[r][c] = 2
    for r in range(h):
        if all(grid[r][c] == 9 for c in range(w)):
            out[r] = [2] * w
    return out

